// One block-chain pose supplies art, slam boxes and the rideable service surface.
export function octopusPose(e){const phase=e.clock%5.2,mode=phase<1.3?'raised':phase<2?'warning':phase<2.35?'slam':phase<4.25?'platform':'fold';const segments=[];for(const side of [-1,1])for(let i=0;i<5;i++){const u=i/4,x=e.x+24+side*(20+i*22),lift=mode==='raised'?-90*u:mode==='fold'?-45*Math.sin(u*Math.PI):0;segments.push({x:x-11,y:e.y+25+lift,w:22,h:14,angle:mode==='raised'?side*-.35:mode==='fold'?side*.5:0});}return {mode,segments,surface:{x:e.x-100,y:e.y+25,w:250,h:12}};}
export function drawOctopus(c,e){const p=octopusPose(e);for(const a of p.segments){c.save();c.translate(a.x+11,a.y+7);c.rotate(a.angle);c.fillStyle='#aaaddb';c.fillRect(-11,-7,22,14);c.fillStyle='#d6dfed';c.fillRect(-9,-6,18,3);c.fillStyle='#55658d';c.fillRect(-8,3,16,1);c.fillStyle='#203c51';c.fillRect(8,-3,5,6);c.restore();}c.fillStyle='#b6b4e1';c.fillRect(e.x,e.y-24,48,44);c.fillStyle='#183049';c.fillRect(e.x+9,e.y-10,8,9);c.fillRect(e.x+30,e.y-10,8,9);if(p.mode==='platform'){c.fillStyle='#ceffec';c.fillRect(p.surface.x,p.surface.y,p.surface.w,3);}if(p.mode==='warning'){c.strokeStyle='#f2c79f';c.setLineDash([6,6]);c.strokeRect(p.surface.x,p.surface.y,p.surface.w,20);c.setLineDash([]);}}
